    'ai.cfg_endpoint' => $t('Compatible endpoint', '兼容接口', 'Kompatibler Endpunkt', 'Endpoint compatible', 'Point d’accès compatible', '호환 엔드포인트', 'Endpoint compatível', '互換エンドポイント'),
